-- Demo taskers from the prototype (design/client). Flagged profiles.is_demo = true; purge before launch.
do $$
declare d jsonb := '[{"k":"t1","f":"Mark","l":"Dela Cruz","t":"Aircon technician","y":8,"b":"Window and split-type aircon specialist. I bring my own tools and pressure washer.","a":"Mandaluyong · Pasig","c":"#044D5E","cat":"Repairs","r":4.9,"j":312,"lat":14.5834,"lng":121.0359,"s":[["Aircon cleaning – window type","Full wash of filter, coil and blower",800,60],["Aircon cleaning – split type","Indoor and outdoor unit, with pressure wash",1200,90],["Freon recharge","Pressure check and recharge",1500,60],["Aircon check-up","Find out why it isn’t cooling",500,45],["Aircon installation","Window or split type, labor only",2500,180]]},{"k":"t2","f":"Ana","l":"Reyes","t":"Home cleaner","y":5,"b":"Deep cleaning for condos and houses. I bring my own cleaning supplies.","a":"Mandaluyong · San Juan","c":"#0A6378","cat":"Cleaning","r":4.8,"j":204,"lat":14.57461,"lng":121.04029,"s":[["Deep cleaning – studio/1BR","Kitchen, bathroom, floors, windows",1500,180],["General cleaning (per hour)","Sweep, wipe, mop and tidy up",350,60]]},{"k":"t3","f":"Jun","l":"Santos","t":"Plumber","y":10,"b":"Leaks, clogs and installations. Fast response for emergencies.","a":"Makati · Mandaluyong","c":"#0A6378","cat":"Repairs","r":4.9,"j":451,"lat":14.58019,"lng":121.02693,"s":[["Leak repair","Faucet, pipe or sink",600,60],["Unclog drain or toilet","Plunger and drain snake included",700,60],["Faucet installation","Labor only, you supply the faucet",450,45],["Water heater install","Single-point heater, labor",1200,120],["Pipe replacement","Per meter, PVC or PPR, labor",350,60]]},{"k":"t4","f":"Rico","l":"Bautista","t":"Home electrician · minor repairs","y":7,"b":"Simple electrical repairs at home: outlets, switches, lights and fans. No new wiring or panel work. Safety first, always.","a":"QC · San Juan","c":"#044D5E","cat":"Repairs","r":4.7,"j":188,"lat":14.5864,"lng":121.04503,"s":[["Outlet or switch repair","Per piece",400,30],["Light fixture install","Ceiling or wall light",500,45]]},{"k":"t5","f":"Paolo","l":"Garcia","t":"Mobile car care","y":6,"b":"I come to your car at home or at the office.","a":"Mandaluyong · Pasig","c":"#044D5E","cat":"Auto","r":4.8,"j":267,"lat":14.56561,"lng":121.03346,"s":[["Change oil (labor)","You supply the oil and filter",500,45],["Battery check and replacement (labor)","May battery tester",300,30],["Car wash at home","Exterior wash and tire shine",450,60],["Brake inspection","Pads, rotor and fluid check",400,45],["Car aircon cleaning","Evaporator and cabin filter",1800,120]]},{"k":"t6","f":"Liza","l":"Mendoza","t":"Handyman","y":4,"b":"Assembly, installs and small home repairs.","a":"Mandaluyong · Makati","c":"#0A6378","cat":"Repairs","r":4.8,"j":139,"lat":14.58278,"lng":121.03375,"s":[["Furniture assembly","Cabinet, bed, table",600,90],["Curtain rod install","Per window",400,45]]},{"k":"t7","f":"Carlo","l":"Villanueva","t":"IT technician","y":5,"b":"Laptop and PC repair, Wi-Fi setup and virus cleanup.","a":"Mandaluyong · Pasig","c":"#044D5E","cat":"Tech","r":4.8,"j":176,"lat":14.57771,"lng":121.04218,"s":[["Laptop or PC troubleshooting","Slow, won’t boot, or virus cleanup",500,60],["Wi-Fi and router setup","Setup, range fix and password reset",600,60]]},{"k":"t8","f":"Ramon","l":"Aquino","t":"Driver and courier","y":9,"b":"Same-day pickups and drop-offs, or I can drive your car for you.","a":"Metro Manila","c":"#0A6378","cat":"Delivery","r":4.9,"j":538,"lat":14.57525,"lng":121.02791,"s":[["Same-day item delivery","Small items that fit a motorcycle top box",250,90],["Driver for hire (4 hours)","I drive YOUR car only. No rides in my own vehicle.",1200,240]]},{"k":"t9","f":"Bea","l":"Santiago","t":"Tutor and piano teacher","y":6,"b":"Patient home tutor for grade school, plus beginner piano.","a":"Mandaluyong · San Juan","c":"#044D5E","cat":"Lessons","r":4.9,"j":142,"lat":14.5902,"lng":121.03985,"s":[["Math and English tutoring","Per hour, grade school to high school",450,60],["Piano lesson for beginners","Kids and adults, keyboard is fine",700,60]]},{"k":"t10","f":"Joy","l":"Navarro","t":"Fitness and wellness coach","y":7,"b":"Home therapy for seniors, stroke recovery and post-surgery rehab.","a":"Mandaluyong · Makati","c":"#0A6378","cat":"Fitness and wellness","r":4.9,"j":221,"lat":14.56646,"lng":121.04124,"s":[["Home fitness session","Strength and cardio workout at your place",800,60],["Wellness coaching session","Habits, sleep and stress routines",700,60]]},{"k":"t11","f":"Marites","l":"Cruz","t":"Caregiver and yaya","y":10,"b":"Elderly care and babysitting. Trained in basic first aid.","a":"Mandaluyong · QC","c":"#044D5E","cat":"Care","r":4.8,"j":97,"lat":14.5811,"lng":121.03228,"s":[["Elderly caregiver (8 hours)","Meals, hygiene and companionship",1200,480],["Yaya or babysitter (per hour)","Kids 1 year old and up",250,60]]},{"k":"t12","f":"Nestor","l":"Ramos","t":"Gardener","y":12,"b":"Lawns, plants and small landscaping jobs.","a":"Mandaluyong · Pasig","c":"#0A6378","cat":"Garden","r":4.7,"j":164,"lat":14.58134,"lng":121.0421,"s":[["Lawn mowing and trimming","Up to 100 sqm, cleanup included",600,120],["Garden cleanup and planting","Weeding, soil and new plants",900,180]]},{"k":"t13","f":"Kim","l":"Tan","t":"Pet groomer","y":4,"b":"Gentle home grooming for dogs and cats.","a":"Mandaluyong · San Juan","c":"#044D5E","cat":"Pets","r":4.9,"j":203,"lat":14.57162,"lng":121.03138,"s":[["Bath and grooming (small dog)","Bath, blow-dry and haircut",650,90],["Nail trim and ear cleaning","Dogs and cats",300,30]]}]'::jsonb; t jsonb; s jsonb; uid uuid; n int;
begin
  for t in select * from jsonb_array_elements(d) loop
    uid := extensions.uuid_generate_v5('6f1c2a7e-0000-4000-8000-000000000001'::uuid, t->>'k');
    insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
    values ('00000000-0000-0000-0000-000000000000',uid,'authenticated','authenticated','demo.'||(t->>'k')||'@tskr.demo',
      extensions.crypt(gen_random_uuid()::text, extensions.gen_salt('bf')),now(),'{"provider":"email","providers":["email"]}',
      jsonb_build_object('given_name',t->>'f','family_name',t->>'l'),now(),now())
    on conflict (id) do nothing;
    update public.profiles set is_demo=true, is_tasker=true, tasker_status='active', signup_role='tasker',
      email_verified_at=now(), phone_verified_at=now() where id=uid;
    insert into public.tasker_profiles(user_id,title,bio,years_experience,photo_path,radius_km,base_lat,base_lng,area_label,is_online,rating_avg,rating_count,jobs_done,color,qr_status)
    values (uid,t->>'t',t->>'b',(t->>'y')::int,'demo/'||(t->>'k'),6,(t->>'lat')::float8,(t->>'lng')::float8,t->>'a',true,
      (t->>'r')::numeric,round((t->>'j')::int*0.6)::int,(t->>'j')::int,t->>'c','approved')
    on conflict (user_id) do nothing;
    n := 0;
    for s in select * from jsonb_array_elements(t->'s') loop
      n := n + 1;
      insert into public.tasker_skills(tasker_id,skill_id,custom_name,description,base_fee,duration_min,slot)
      select uid,(select min(sk.id) from public.skills sk join public.skill_categories c on c.id=sk.category_id where c.name=t->>'cat'),
        s->>0,s->>1,(s->>2)::numeric,(s->>3)::int,n
      where not exists (select 1 from public.tasker_skills where tasker_id=uid and slot=n);
    end loop;
  end loop;
end $$;
